"use client";

interface Product {
  id: string;
  name: string;
  brand?: string;
  category?: string;
  ingredients?: string;
  timeOfDay?: string;
  routineProductId?: string;
  stepOrder?: number;
   skipDays?: string[];
}

interface ProductListProps {
  products: Product[];
  onRemove?: (productId: string, timeOfDay?: string, routineProductId?: string) => void;
  showRemove?: boolean;
  emptyLabel?: string;
  onReorder?: (
    routineProductId: string,
    direction: "up" | "down",
    context?: "MORNING" | "NIGHT"
  ) => void;
  timeOfDayContext?: "MORNING" | "NIGHT";
  reorderingProductId?: string | null;
}

const formatTimeOfDay = (value?: string) => {
  if (!value) return "";
  if (value === "MORNING") return "Morning";
  if (value === "NIGHT") return "Night";
  return "All Day";
};

const formatSkipDays = (days?: string[]) => {
  if (!days || days.length === 0) return "Daily";
  const shortMap: Record<string, string> = {
    MONDAY: "Mon",
    TUESDAY: "Tue",
    WEDNESDAY: "Wed",
    THURSDAY: "Thu",
    FRIDAY: "Fri",
    SATURDAY: "Sat",
    SUNDAY: "Sun",
  };
  const formatted = days.map((d) => shortMap[d] || d);
  return `Skips ${formatted.join(", ")}`;
};

export default function ProductList({
  products,
  onRemove,
  showRemove = false,
  emptyLabel = "No products added yet",
  onReorder,
  timeOfDayContext,
  reorderingProductId,
}: ProductListProps) {
  if (products.length === 0) {
    return (
      <div className="text-center py-6 text-gray-500 text-sm">
        {emptyLabel}
      </div>
    );
  }

  return (
    <div className="space-y-3">
      {products.map((product, index) => (
        <div
          key={product.routineProductId || product.id}
          className="flex items-start justify-between p-4 bg-white border border-gray-200 rounded-lg hover:shadow-md transition"
        >
          <div className="flex-1">
            <div className="flex items-center gap-2 text-xs font-semibold uppercase tracking-wide text-gray-400 mb-1">
              <span className="text-indigo-600">Step {index + 1}</span>
            </div>
            <h3 className="font-semibold text-gray-900">{product.name}</h3>
            {(product.brand || product.timeOfDay) && (
              <div className="flex flex-wrap items-center gap-2 text-sm text-gray-600 mt-1">
                {product.brand && <span>{product.brand}</span>}
                {product.timeOfDay && (
                  <span className="inline-flex items-center rounded-full bg-slate-100 px-2 py-0.5 text-xs font-medium text-slate-700">
                    {formatTimeOfDay(product.timeOfDay)}
                  </span>
                )}
              </div>
            )}
            <div className="text-xs text-gray-500 mt-1">
              {formatSkipDays(product.skipDays)}
            </div>
            {product.category && (
              <span className="inline-block mt-1 px-2 py-1 text-xs bg-indigo-100 text-indigo-700 rounded">
                {product.category}
              </span>
            )}
            {product.ingredients && (
              <p className="mt-2 text-sm text-gray-500 line-clamp-2">
                {product.ingredients}
              </p>
            )}
          </div>
          <div className="flex flex-col items-end gap-2 ml-4">
            {onReorder && product.routineProductId && (
              <div className="flex flex-col gap-1">
                <button
                  type="button"
                  disabled={
                    index === 0 || reorderingProductId !== null
                  }
                  onClick={() =>
                    onReorder(
                      product.routineProductId,
                      "up",
                      timeOfDayContext
                    )
                  }
                  className={`text-xs px-2 py-1 rounded border ${
                    index === 0 || reorderingProductId !== null
                      ? "text-gray-400 border-gray-200 cursor-not-allowed bg-gray-50"
                      : "text-indigo-700 border-indigo-200 hover:bg-indigo-50"
                  }`}
                >
                  Move Up
                </button>
                <button
                  type="button"
                  disabled={
                    index === products.length - 1 ||
                    reorderingProductId !== null
                  }
                  onClick={() =>
                    onReorder(
                      product.routineProductId,
                      "down",
                      timeOfDayContext
                    )
                  }
                  className={`text-xs px-2 py-1 rounded border ${
                    index === products.length - 1 ||
                    reorderingProductId !== null
                      ? "text-gray-400 border-gray-200 cursor-not-allowed bg-gray-50"
                      : "text-indigo-700 border-indigo-200 hover:bg-indigo-50"
                  }`}
                >
                  Move Down
                </button>
              </div>
            )}
            {showRemove && onRemove && (
              <button
                onClick={() =>
                  onRemove(product.id, product.timeOfDay, product.routineProductId)
                }
                className="text-red-600 hover:text-red-700 transition"
                title="Remove product"
              >
                <svg
                  className="w-5 h-5"
                  fill="none"
                  stroke="currentColor"
                  viewBox="0 0 24 24"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2}
                    d="M6 18L18 6M6 6l12 12"
                  />
                </svg>
              </button>
            )}
          </div>
        </div>
      ))}
    </div>
  );
}
